#!/usr/bin/env node
/**
 * Build the mini-app Worker's generated files from each app's `app.json`.
 *
 *   mini-apps/apps/index.html     the dashboard: every app's title, description, and link
 *   mini-apps/apps/routes.gen.ts  the route table worker.ts imports: app name → its api.mjs
 *
 * `scripts/cf-mini.sh` runs this before every upload or deploy, so the
 * dashboard always lists exactly the apps being shipped. No model step: the
 * output depends only on the folders, sorted by name, so the same tree always
 * writes the same bytes.
 *
 * Each folder under `mini-apps/apps/` is one app. It needs a lowercase name
 * (letters, digits, hyphens; it is the URL path) and an `app.json` whose
 * `title` and `description` are non-empty strings. Any failure names the
 * folder, writes nothing, and exits 1, which stops the upload or deploy.
 */

import { existsSync, mkdirSync, readdirSync, readFileSync, writeFileSync } from "node:fs";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";
import { isMain, parseCli } from "./lib-cli.mjs";

const NAME = /^[a-z0-9][a-z0-9-]*$/;

const escapeHtml = text =>
  text.replace(/[&<>"']/g, ch => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" })[ch]);

/** The app's manifest, or the reason it is unusable. */
function readApp(appsDir, name) {
  const where = `mini-apps/apps/${name}`;
  if (!NAME.test(name)) return { error: `${where}: the folder name must use only lowercase letters, digits, and hyphens` };
  const manifest = join(appsDir, name, "app.json");
  if (!existsSync(manifest)) return { error: `${where}: app.json is missing` };
  let app;
  try {
    app = JSON.parse(readFileSync(manifest, "utf8"));
  } catch (error) {
    return { error: `${where}: app.json is not valid JSON (${error.message})` };
  }
  for (const field of ["title", "description"]) {
    if (typeof app?.[field] !== "string" || !app[field].trim()) {
      return { error: `${where}: app.json needs a "${field}" (a non-empty string)` };
    }
  }
  return { name, title: app.title.trim(), description: app.description.trim(), api: existsSync(join(appsDir, name, "api.mjs")) };
}

/** Every app folder, sorted by name, or the list of failures. */
export function readApps(appsDir) {
  const names = existsSync(appsDir)
    ? readdirSync(appsDir, { withFileTypes: true })
        .filter(entry => entry.isDirectory() && !entry.name.startsWith("."))
        .map(entry => entry.name)
        .sort((a, b) => (a < b ? -1 : a > b ? 1 : 0))
    : [];
  const apps = names.map(name => readApp(appsDir, name));
  const errors = apps.filter(app => app.error).map(app => app.error);
  return errors.length ? { errors } : { apps };
}

export function dashboardHtml(apps) {
  const list = apps.length
    ? `<ul>\n${apps
        .map(app =>
          `  <li><a href="./${app.name}/"><span class="title">${escapeHtml(app.title)}</span>` +
          `<span class="description">${escapeHtml(app.description)}</span></a></li>`)
        .join("\n")}\n</ul>`
    : "<p>No mini apps yet. Ask the agent to make one.</p>";
  return `<!doctype html>
<!-- Generated by scripts/mini-dashboard.mjs from each app.json. Do not edit. -->
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Mini apps</title>
<style>
  :root { color-scheme: light dark; font-family: system-ui, sans-serif; }
  body { max-width: 40rem; margin: 0 auto; padding: 1.5rem 1rem; line-height: 1.5; }
  h1 { font-size: 1.5rem; margin: 0 0 1rem; }
  ul { list-style: none; margin: 0; padding: 0; }
  li + li { margin-top: 0.75rem; }
  a { display: block; padding: 0.875rem 1rem; border: 1px solid GrayText; border-radius: 0.5rem; color: inherit; text-decoration: none; }
  a:hover, a:focus-visible { border-color: currentColor; }
  .title { display: block; font-weight: 600; color: LinkText; }
  .description { display: block; }
</style>
</head>
<body>
<main>
<h1>Mini apps</h1>
${list}
</main>
</body>
</html>
`;
}

export function routesTs(apps) {
  const withApi = apps.filter(app => app.api);
  const imports = withApi.map((app, i) => `import api${i} from ${JSON.stringify(`./${app.name}/api.mjs`)};\n`).join("");
  const entries = withApi.map((app, i) => `\t${JSON.stringify(app.name)}: api${i},\n`).join("");
  return `// Generated by scripts/mini-dashboard.mjs. Do not edit.
// Each entry is the default export of apps/<name>/api.mjs: { fetch(request, env, ctx) }.
${imports}${imports ? "\n" : ""}export default {
${entries}};
`;
}

/** Write `path` only when its bytes change. */
function writeIfChanged(path, text) {
  if (existsSync(path) && readFileSync(path, "utf8") === text) return;
  writeFileSync(path, text);
}

if (isMain(import.meta.url)) {
  const usage = "usage: node scripts/mini-dashboard.mjs [--dir <mini-apps folder>]  (writes apps/index.html and apps/routes.gen.ts; exits 1 on a bad app.json)";
  const { values } = parseCli({ usage, options: { dir: { type: "string" } } });
  const dir = values.dir ? resolve(values.dir) : resolve(dirname(fileURLToPath(import.meta.url)), "../mini-apps");
  if (!existsSync(dir)) {
    console.error(`mini-dashboard: ERROR — no mini-apps folder at ${dir}`);
    process.exit(1);
  }
  const appsDir = join(dir, "apps");
  const { apps, errors } = readApps(appsDir);
  if (errors) {
    for (const error of errors) console.error(`mini-dashboard: ERROR — ${error}`);
    process.exit(1);
  }
  mkdirSync(appsDir, { recursive: true });
  writeIfChanged(join(appsDir, "index.html"), dashboardHtml(apps));
  writeIfChanged(join(appsDir, "routes.gen.ts"), routesTs(apps));
  console.log(`mini-dashboard: ${apps.length} app(s) — wrote apps/index.html and apps/routes.gen.ts`);
}
